def enrich(demos, read, missing, mde_d):
    for d in demos:
        id = d['id']
        src = read(Path(d['path']) / 'results.json')
        d['source_claim_type'] = src.get('claim_type')
        d['reanalysis_claim_type'] = 'capability'
        d['independent_unit'] = UNIT[id]
        d['support'] = LIMIT[id]
        d['package_active'] = id != 'GENCAD_V2'
        d['package_status'] = 'ARCHIVED_REPLACED_BY_V3' if id == 'GENCAD_V2' else 'ACTIVE_AT_R3_SNAPSHOT'
        d['attrition'] = ATTRITION.get(id, dict(candidate=None, retained=None, excluded=None, reason='The full specimen selection denominator/lineage is unidentified for the main metric. UNKNOWN; do not invent 0% attrition.'))
        a = d['attrition']
        a['excluded_fraction'] = a['excluded'] / a['candidate'] if a['candidate'] else None
        if id == 'X25':
            for row in src['risk_load_quantiles']:
                e = missing(id, f"{row['configuration']} load at risk={row['risk']}", row['force_N'], 'N', 'UNKNOWN: original stratified independent-specimen model/refit bootstrap available; manufacturing batch IDs absent, so no batch-cluster replacement is identified.', 36, None)
                e.update(primary=False, original_reported_ci95=row['bootstrap95_N'], original_interval_locator='/risk_load_quantiles', original_CI_assumptions='Lognormal S–N, common slope, independent censoring;400 specimen resamples', input_resolution='PER_TOOTH', resolution_level='PER_TOOTH')
                d['metrics'].append(e)
        if id == 'X32':
            c = src['failure_coverage']
            e = missing(id, 'framework share of attributed crown failures', 4 / 230, 'andel', 'UNKNOWN: disjoint finite-cohort count4/230, but cause-to-patient assignments absent.149 patients share230 failures; cannot cluster-bootstrap patients.', 230, 149)
            e.update(primary=False, original_reported_ci95=None, naive_row_ci95=[float(stats.beta.ppf(0.025, 4, 227)), float(stats.beta.ppf(0.975, 5, 226))], before_method='Counterfactual IID-failure exact interval; not a valid patient interval', cohort_patients=401, failed_crown_patients=149, finite_mapping_bound=[0, 4 / 230])
            d['metrics'].append(e)
            for comp in src['case_level_comparisons']:
                for m in d['metrics']:
                    if m['metric'].startswith(comp['demo'] + ' '):
                        m['original_reported_ci95'] = comp['intervals'].get('any_patient_change_ci95', comp['intervals'].get('any_source_family_change_ci95')) if 'any-change' in m['metric'] else comp['intervals']['unit_rate_ci95'][0]
                        m['original_interval_locator'] = '/case_level_comparisons/' + comp['demo'] + '/intervals'
        if id == 'X29':
            raw = read(Path(d['path']) / 'raw/MEASUREMENTS.json') + read(Path(d['path']) / 'raw/R3_MEASUREMENTS.json')
            for row in raw:
                if row['id'] == 'PMC10788321_3Y_angle30':
                    continue
                n = int(row['n'])
                sd = float(row['sd_N'])
                v = float(row['mean_N'])
                h = stats.t.ppf(0.975, n - 1) * sd / n ** 0.5
                e = missing(id, 'published ' + row['id'] + ' mean fracture load', v, 'N', 'UNKNOWN: one source study/batch; reported specimen summary only. Independent-specimen t scenario below is not batch bootstrap.', n, 1)
                e.update(primary=False, reported_specimen_t95_if_IID=[float(v - h), float(v + h)], mde_native_if_IID_specimens=mde_d(n) * sd)
                d['metrics'].append(e)
        if id == 'X31':
            rounded = {'fully_guided': [0.272, 0.315], 'pilot_guided': [0.475, 0.528], 'freehand': [0.527, 0.58], 'dynamic_navigation': [0.236, 0.276]}
            for m in d['metrics']:
                if 'apex-scenario' in m['metric']:
                    d['original_intervals_note'] = 'Original already uses patient bootstrap for guide fractions; new IID column is a hypothetical comparison, not an original error.'
                    m['original_reported_ci95'] = rounded[m['metric'].split(' ')[0]]
                    m['original_interval_locator'] = 'README_DEMO.md: nervmarginal table; rounded percentages converted to fraction'
        if id == 'X3':
            m = next((m for m in d['metrics'] if m['metric'] == 'R3 paired p95 difference vs mirror'))
            m['original_reported_ci95'] = src['rounds']['R3']['decision']['paired_patient_bootstrap95ci_mm']
            m['original_interval_locator'] = '/rounds/R3/decision/paired_patient_bootstrap95ci_mm'
        for m in d['metrics']:
            if 'input_resolution' not in m:
                m['input_resolution'] = 'PER_TOOTH'
            if id in {'X7', 'X21', 'PROOF_LANE', 'GENCAD_V2', 'GENCAD_V3', 'X4'}:
                m['input_resolution'] = 'PER_ARCH'
            if id == 'X33':
                m['input_resolution'] = 'PER_POINT' if 'same-heat' in m['metric'] else 'POPULATION'
            if id in {'X13', 'X14', 'X10', 'X17', 'X19', 'X16', 'X28', 'X23', 'X24', 'X29'}:
                m['input_resolution'] = 'PER_SURFACE_REGION'
            if id == 'X18B':
                m['input_resolution'] = 'PER_POINT'
                m['resolution_level'] = 'PER_POINT'
            if 'resolution_level' not in m:
                m['resolution_level'] = 'POPULATION'
            m['time_scale'] = 'SIMULTANEOUS'
            m['independent_unit'] = UNIT[id]
            m['independence_status'] = 'ASSUMED_CASE_PROXY_NOT_VERIFIED_PATIENT_SAMPLING' if m.get('cluster_ci95') else 'NOT_IDENTIFIED_OR_NOT_APPLICABLE'
            m['phenomenological_debt'] = 'Case IDs do not establish population IID or transport. Replace with specimen/donor/patient/center/batch lineage and matched untouched reference data.'
    return [m for d in demos for m in d['metrics']]
